briefCalls.responseText:
{
  "primitive": "intro_briefing",
  "topic": "Compose and decompose numbers 11-19 using equations (e.g., 14 = 10 + 4)",
  "subject": "General",
  "gradeLevel": "kindergarten",
  "estimatedTime": "15-20 minutes",
  "hook": {
    "type": "scenario",
    "content": "Imagine you have a giant box of 14 crayons! You decide to put 10 crayons neatly into a special pencil box, and keep 4 crayons in your hand to draw with right now. Together, your whole pile is still 14 crayons, just broken into two friendly parts!",
    "visualTheme": "counting"
  },
  "bigIdea": {
    "statement": "Numbers from 11 to 19 are made of one big group of ten and some extra ones.",
    "whyItMatters": "Seeing numbers as a group of ten plus extras helps us count faster, do bigger math easily, and understand how numbers work all the way up to 100!"
  },
  "objectives": [
    {
      "id": "obj1",
      "text": "Build numbers 11 through 19 using a bundle of ten counters and some extra single counters",
      "verb": "apply",
      "icon": "puzzle"
    },
    {
      "id": "obj2",
      "text": "Explain how numbers 11-19 are made of a ten and leftover ones",
      "verb": "explain",
      "icon": "lightbulb"
    },
    {
      "id": "obj3",
      "text": "Write equations like 14 = 10 + 4 to show a ten and some ones",
      "verb": "create",
      "icon": "pencil"
    }
  ],
  "prerequisites": {
    "shouldKnow": [
      "Count objects up to 20 reliably",
      "Understand that a group of 10 items can be bundled together as 'one ten'"
    ],
    "quickCheck": {
      "question": "If you count 10 counting bears and put them in a cup, how many bears are inside?",
      "answer": "10 bears",
      "hint": "Think about how many bears you started with and put into the cup together."
    }
  },
  "roadmap": [
    {
      "phase": "Explore",
      "description": "Build teen numbers using real objects and a group of ten.",
      "activities": [
        "Count out 10 items to make a 'ten-frame' stick",
        "Add extra counters to make numbers like 12, 15, and 18"
      ]
    },
    {
      "phase": "Learn",
      "description": "Discover the hidden parts inside teen numbers.",
      "activities": [
        "Say aloud how numbers 11-19 hide a ten and some extra ones",
        "Practice saying '13 is 10 and 3'"
      ]
    },
    {
      "phase": "Practice",
      "description": "Connect the physical objects to written math equations.",
      "activities": [
        "Match blocks to written equations like 16 = 10 + 6",
        "Write your own addition equations for numbers between 11 and 19"
      ]
    }
  ],
  "connections": {
    "buildingFrom": [
      "Counting to 20 by ones",
      "Making groups of 10 inside larger numbers"
    ],
    "leadingTo": [
      "Adding and subtracting numbers beyond 20",
      "Understanding place value with tens and hundreds"
    ],
    "realWorld": [
      "Counting a full carton of 10 eggs plus extra loose eggs on the counter",
      "Organizing toys into boxes of ten plus extras"
    ]
  },
  "mindset": {
    "encouragement": "Teens numbers can look a little tricky because their names sound backward (like fourteen starting with four instead of ten), but once you look for the hidden ten, you will master them easily!",
    "growthTip": "Always look for your group of 10 first before counting the leftover ones!"
  }
}
